          "de": "Automatische Umrechnung und Anzeige von Kick Drops- und Abzeichen-Dauern sowie verbleibender Zeit in Stunden (5 h, 10 h) und Tagen (24 h+).",
          "it": "Conversione e visualizzazione automatica in ore (5 h, 10 h) e in giorni (24 h+) delle durate e del tempo rimanente dei Drop e degli stemmi Kick.",
          "pl": "Automatyczna konwersja i wyświetlanie czasu trwania oraz pozostałego czasu Dropsów i odznak Kick w godzinach (5 h, 10 h) i dniach (24 h+).",
          "tr": "Kick Drops ve rozet süreleri ile kalan sürenin otomatik olarak saat (5 sa, 10 sa) ve gün (24 sa+) cinsinden dönüştürülmesi ve gösterilmesi.",
          "ru": "Автоматическое преобразование и отображение длительности и оставшегося времени Drops и значков Kick в часах (5 ч, 10 ч) и днях (24 ч+).",
          "ja": "Kickのドロップおよびバッジの所要時間と残り時間を時間（5時間、10時間）や日数（24時間以上）に自動換算して表示。",
          "ko": "Kick 드롭스 및 배지의 진행 시간과 남은 시간을 시간(5시간, 10시간) 및 일 단위(24시간 이상)로 자동 변환하여 표시.",
          "ar": "تحويل وعرض تلقائي لمدد ومتبقي وقت Drops وشارات Kick بالساعات (5 س، 10 س) والأيام (24 س+).",
