          "sv": "Automatisk konvertering och visning av varaktigheter och återstående tid för Kick Drops och märken i timmar (5 tim, 10 tim) och dagar (24 tim+).",
          "cs": "Automatický převod a zobrazení doby trvání a zbývajícího času Drops a odznaků Kick v hodinách (5 h, 10 h) a dnech (24 h+)."
