          "ko": "브라우저에서 Twitch 계정에 로그인되어 있지 않을 때 드롭스와 배지 탭에서 이를 알려주는 안내를 추가했습니다.",
          "ar": "إضافة تنبيه في علامتي تبويب Drops والشارات يوضح ما إذا كان حساب Twitch غير مسجل الدخول في المتصفح.",
          "id": "Menambahkan pengingat di tab Drops dan Lencana yang menunjukkan jika akun Twitch belum terhubung di browser.",
          "nl": "Herinnering toegevoegd in de tabbladen Drops en Badges die aangeeft of het Twitch-account niet is ingelogd in de browser.",
          "sv": "Lade till en påminnelse i flikarna Drops och Märken som visar om Twitch-kontot inte är inloggat i webbläsaren.",
          "cs": "Přidáno upozornění v kartách Drops a Odznaky informující o nepřihlášeném účtu Twitch v prohlížeči."
