          "fr": "L'alerte « Nouveau badge » part maintenant quand le badge est vraiment disponible à récupérer. Un badge qui arrive prochainement garde son alerte, avec un texte « bientôt disponible ».",
          "en": "The “New badge” alert now fires when the badge can really be earned. A badge coming soon keeps its alert, worded as “coming soon”.",
          "uk": "Сповіщення «Новий значок» тепер надходить, коли значок справді можна отримати. Значок, що з'явиться незабаром, зберігає своє сповіщення з текстом «незабаром».",
          "es": "La alerta «Nueva insignia» ahora salta cuando la insignia se puede conseguir de verdad. Una insignia que llega pronto conserva su alerta, con el texto «próximamente».",
          "pt-BR": "O alerta «Novo emblema» agora dispara quando o emblema pode mesmo ser conquistado. Um emblema que chega em breve mantém o alerta, com o texto «em breve».",
          "de": "Die Meldung „Neues Abzeichen“ kommt jetzt, wenn sich das Abzeichen wirklich verdienen lässt. Ein bald kommendes Abzeichen behält seine Meldung, mit dem Text „bald verfügbar“.",
          "it": "L'avviso «Nuovo badge» ora scatta quando il badge si può davvero ottenere. Un badge in arrivo mantiene il suo avviso, con il testo «in arrivo».",
          "pl": "Alert „Nowa odznaka” przychodzi teraz, gdy odznakę naprawdę można zdobyć. Odznaka, która pojawi się wkrótce, zachowuje swój alert z tekstem „wkrótce”.",
          "tr": "«Yeni rozet» uyarısı artık rozet gerçekten kazanılabilir olduğunda geliyor. Yakında gelecek bir rozet, «yakında» metniyle uyarısını koruyor.",
          "ru": "Уведомление «Новый значок» теперь приходит, когда значок действительно можно получить. Значок, который появится скоро, сохраняет своё уведомление с пометкой «скоро».",
          "ja": "「新しいバッジ」の通知は、バッジを実際に獲得できるようになった時点で届くようになりました。近日登場のバッジも、「まもなく」の文言で通知されます。",
          "ko": "'새 배지' 알림이 이제 배지를 실제로 받을 수 있게 됐을 때 와요. 곧 나오는 배지는 '곧 획득 가능' 문구로 계속 알려드려요.",
