          "ja": "「Drops セッションを計画」を修正しました。同じキャンペーンの Drops を順番に足し算しなくなり（Twitch は同時に進めます）、視聴済みの分数が差し引かれ、キャンペーンは折りたためて、使える時間はワンクリックで選べ、各 Drop に残り時間が表示されます。入力中にフォーカスが外れることもなくなりました。",
