          "it": "Impostazioni riorganizzate: Player e Anteprime e chat sono ora separati, le schede del browser passano al Player, la notifica di aggiornamento va in Generale e il doppione dell'interruttore della cronologia Drops è sparito. Gli avvisi di diretta, categoria e titolo mostrano uno stato misto quando i tuoi streamer non hanno tutti la stessa impostazione.",
          "pl": "Ustawienia uporządkowane: Odtwarzacz oraz Podglądy i czat są teraz osobno, karty przeglądarki trafiły do Odtwarzacza, powiadomienie o aktualizacji jest w Ogólnych, a zdublowany przełącznik historii Dropów zniknął. Alerty o live, kategorii i tytule pokazują stan mieszany, gdy streamerzy mają różne ustawienia.",
          "tr": "Ayarlar yeniden düzenlendi: Oynatıcı ile Önizlemeler ve sohbet artık ayrı, tarayıcı sekmeleri Oynatıcı'ya taşındı, güncelleme bildirimi Genel'e geçti ve yinelenen Drops geçmişi anahtarı kalktı. Canlı, kategori ve başlık uyarıları, yayıncıların ayarı aynı değilse karışık durumu gösteriyor.",
          "ru": "Настройки переупорядочены: «Плеер» и «Превью и чат» теперь отдельно, вкладки браузера перешли в «Плеер», уведомление об обновлении — в «Общие», а дублирующий переключатель истории Drops убран. Оповещения о начале эфира, категории и названии показывают смешанное состояние, если у стримеров разные настройки.",
          "ja": "設定を整理しました。「プレーヤー」と「プレビューとチャット」を分け、ブラウザのタブはプレーヤーへ、更新通知は「一般」へ移動し、重複していた Drops 履歴のスイッチを削除しました。ライブ・カテゴリ・タイトルのアラートは、配信者ごとに設定が異なる場合に混在状態を表示します。",
          "ko": "설정을 재구성했습니다. 플레이어와 미리보기·채팅을 분리하고, 브라우저 탭은 플레이어로, 업데이트 알림은 일반으로 옮겼으며, 중복된 Drops 기록 스위치를 없앴습니다. 라이브·카테고리·제목 알림은 스트리머마다 설정이 다를 때 혼합 상태로 표시됩니다.",
          "ar": "أُعيد تنظيم الإعدادات: «المشغّل» و«المعاينات والدردشة» صارا منفصلين، وانضمت تبويبات المتصفح إلى صفحة المشغّل، وانتقل إشعار التحديث إلى عام، وزال مفتاح سجل Drops المكرر. تعرض تنبيهات البث والفئة والعنوان الآن حالة مختلطة عندما لا يتشارك بثّاثوك الإعداد نفسه.",
