          "tr": "Bir yayıncıyı, ana ekrandaki kartından başka bir platformdaki hesabına bağla: bir düğme, diğer hesaba bir tık ve ikisi de canlıyken tek kart ve tek bildirim alırsın. Ayarlara gitmen gerekmez.",
          "ru": "Связывай стримера с его аккаунтом на другой платформе прямо с карточки на главной: одна кнопка, один клик по второму аккаунту — и когда оба в эфире, ты видишь одну плитку и одно уведомление. В настройки заходить не нужно.",
          "ja": "ホームのカードから、配信者を別プラットフォームのアカウントに直接リンクできるようになりました。ボタンを押して相手のアカウントを選ぶだけで、両方が配信中でもカードと通知は1つだけ。設定画面を開く必要はありません。",
          "ko": "홈 카드에서 바로 스트리머를 다른 플랫폼 계정과 연결할 수 있습니다. 버튼을 누르고 상대 계정을 선택하면 두 계정이 모두 라이브일 때도 카드와 알림이 하나만 표시됩니다. 설정에 들어갈 필요가 없습니다.",
          "ar": "اربط بثّاثًا بحسابه على منصة أخرى مباشرة من بطاقته في الصفحة الرئيسية: زر واحد، ونقرة واحدة على الحساب الآخر، فتحصل على بطاقة واحدة وإشعار واحد عندما يبث الحسابان. دون المرور بالإعدادات.",
