          ar: "وضع الشارات التلقائي: صار التبويب يتجاوز وحده شاشات الحجب (المحتوى للبالغين، موافقة الدردشة) التي كانت تترك البث متوقفًا والشارات متجمدة. وتُعاد جودة 360p والصوت شبه الصامت بعد الإعلانات وإعادة تشغيل البث.",
