          ja: "レイアウト：「一般とヘルプ」で上部バーのタブと設定の項目の並び順を変更し、使わないもの（履歴など）を非表示にできます。",
          ko: "배치: 일반 및 도움말에서 상단 바 탭과 설정 항목의 순서를 바꾸고, 쓰지 않는 것(예: 기록)을 숨길 수 있습니다.",
