          ja: "StreamPulse の更新をバージョンごとに1回、通知でお知らせし、クリックで新着情報を開けます。設定の「アラート」タブでオフにできます。",
          ko: "StreamPulse 업데이트를 버전당 한 번 알림으로 알려주고, 클릭하면 새 소식이 열립니다. 설정의 알림 탭에서 끌 수 있습니다.",
